// ===== Read Message =====
// Turns Meta's webhook envelope into one item per customer message, and builds the
// single query that loads everything the engine needs.
const out = [];
const digits = (s) => String(s || '').replace(/\D/g, '');

for (const it of $input.all()) {
  const j = it.json;
  const graph = j.graph_version || 'v25.0';
  const body = (j.body && j.body.entry) ? j.body : (j.entry ? j : null);
  if (!body) continue;

  for (const entry of body.entry || []) {
    for (const change of entry.changes || []) {
      const v = change.value || {};
      const pnid = (v.metadata || {}).phone_number_id;
      if (!pnid) continue;                      // not a message webhook
      const contacts = v.contacts || [];

      for (const m of v.messages || []) {       // statuses (sent/delivered/read) have no .messages
        const wa = digits(m.from);
        if (!wa) continue;
        const prof = ((contacts.find((c) => digits(c.wa_id) === wa) || contacts[0] || {}).profile) || {};

        let kind = 'other'; let id = ''; let text = '';
        if (m.type === 'text') { kind = 'text'; text = String((m.text || {}).body || '').trim(); }
        else if (m.type === 'interactive') {
          const r = (m.interactive || {}).list_reply || (m.interactive || {}).button_reply;
          if (r) { kind = 'choice'; id = String(r.id || ''); text = String(r.title || ''); }
        } else if (m.type === 'button') { kind = 'text'; text = String((m.button || {}).text || '').trim(); }

        const msg = { phone_number_id: pnid, wa_id: wa, profile_name: prof.name || '', kind, id, text,
                      graph_version: graph, msg_id: m.id || ('gen-' + Date.now() + '-' + Math.random().toString(36).slice(2)) };

        out.push({ json: {
          sql: 'SELECT salon_context($1,$2) AS ctx, claim_message($3) AS fresh, $4::jsonb AS msg',
          params: [pnid, wa, msg.msg_id, JSON.stringify(msg)],
        } });
      }
    }
  }
}
return out;

// ===== Booking Engine =====
// No AI. A fixed state machine plus real availability maths.
// In : one item per inbound message  { ctx, fresh, msg }   (from "Load Salon + Session")
// Out: the WhatsApp reply, the new session state, and - when the customer confirms -
//      the database action to run next.
//
// The engine NEVER decides that a slot is free. It only offers slots that the maths
// says are free; the database has the final word when the booking is written.

const OUT = [];
const clip = (s, n) => (String(s).length > n ? String(s).slice(0, n - 1) + '\u2026' : String(s));
const money = (v, cur) => {
  const n = Number(v || 0);
  if (!n) return '';
  const sym = { GBP: '\u00a3', USD: '$', EUR: '\u20ac', PKR: 'Rs ', AED: 'AED ', INR: '\u20b9' }[cur] || (cur + ' ');
  return sym + (n % 1 === 0 ? n.toFixed(0) : n.toFixed(2));
};
const dur = (m) => (m >= 60 ? (m / 60 % 1 === 0 ? (m / 60) + 'h' : Math.floor(m / 60) + 'h' + (m % 60) + 'm') : m + ' min');

// ---------- WhatsApp payload builders (Cloud API limits enforced by clip()) ----------
const base = (to) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const txt = (to, body) => ({ ...base(to), type: 'text', text: { preview_url: false, body: clip(body, 4096) } });
const btns = (to, body, opts) => ({
  ...base(to), type: 'interactive',
  interactive: {
    type: 'button', body: { text: clip(body, 1024) },
    action: { buttons: opts.slice(0, 3).map((o) => ({ type: 'reply', reply: { id: clip(o.id, 256), title: clip(o.title, 20) } })) },
  },
});
const lst = (to, body, buttonText, sectionTitle, rows) => ({
  ...base(to), type: 'interactive',
  interactive: {
    type: 'list', body: { text: clip(body, 1024) },
    action: {
      button: clip(buttonText, 20),
      sections: [{
        title: clip(sectionTitle, 24),
        rows: rows.slice(0, 10).map((r) => {
          const row = { id: clip(r.id, 200), title: clip(r.title, 24) };
          if (r.description) row.description = clip(r.description, 72);
          return row;
        }),
      }],
    },
  },
});

// A list can hold 10 rows. Anything longer gets a "More" row and a page in the session.
function paged(options, page) {
  const PER = 9;
  if (options.length <= 10) return { rows: options, more: false };
  const start = page * PER;
  const slice = options.slice(start, start + PER);
  const rows = slice.slice();
  if (start + PER < options.length) rows.push({ id: '__more', title: 'More \u25b8', description: 'Show the next options' });
  else if (page > 0) rows.push({ id: '__first', title: '\u25c2 Back to start', description: 'Show the first options' });
  return { rows, more: true };
}

// ---------- availability ----------
function hhmmToMin(t) { const p = String(t || '0:0').split(':'); return (+p[0]) * 60 + (+p[1] || 0); }
const minToHHMM = (m) => String(Math.floor(m / 60)).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');

function staffForService(ctx, serviceId) {
  return (ctx.staff || []).filter((s) => !s.service_ids || !s.service_ids.length || s.service_ids.includes(serviceId));
}

// Every free start time on one calendar day, and who could do it.
function daySlots(ctx, serviceId, staffId, dayISO) {
  const t = ctx.tenant;
  const service = (ctx.services || []).find((s) => s.id === serviceId);
  if (!service) return [];
  const block = service.duration_min + (t.buffer_min || 0);   // chair time + cleanup
  const step = t.slot_step_min || 15;
  const zone = t.timezone;

  const day = DateTime.fromISO(dayISO, { zone });
  if (!day.isValid) return [];
  const weekday = day.weekday % 7;                            // luxon 1..7 (Mon..Sun) -> 0..6 (Sun..Sat)
  const salon = (ctx.opening_hours || []).find((h) => h.weekday === weekday);
  if (!salon || salon.closed) return [];

  const now = DateTime.fromISO(ctx.now, { zone });
  const earliest = now.plus({ minutes: t.min_notice_min || 0 });
  const latestDay = now.plus({ days: t.max_advance_days || 30 }).endOf('day');
  if (day.endOf('day') < earliest || day > latestDay) return [];

  const salonOpen = hhmmToMin(salon.opens);
  const salonClose = hhmmToMin(salon.closes);
  const busy = ctx.busy || [];
  const byTime = new Map();

  for (const person of staffForService(ctx, serviceId)) {
    if (staffId && person.id !== staffId) continue;

    let open = salonOpen; let close = salonClose;
    const own = (person.hours || []).find((h) => h.weekday === weekday);
    if (own) {
      if (own.off) continue;
      open = Math.max(open, hhmmToMin(own.opens));
      close = Math.min(close, hhmmToMin(own.closes));
    }
    if (close - open < block) continue;

    const taken = busy.filter((b) => b.staff_id === person.id)
      .concat((person.time_off || []).map((o) => ({ starts_at: o.starts_at, ends_at: o.ends_at })))
      .map((b) => ({ s: DateTime.fromISO(b.starts_at, { zone }), e: DateTime.fromISO(b.ends_at, { zone }) }));

    for (let m = open; m + block <= close; m += step) {
      const start = day.set({ hour: Math.floor(m / 60), minute: m % 60, second: 0, millisecond: 0 });
      const end = start.plus({ minutes: block });
      if (start < earliest || start > latestDay) continue;
      if (taken.some((b) => start < b.e && end > b.s)) continue;   // half-open overlap
      const key = minToHHMM(m);
      if (!byTime.has(key)) byTime.set(key, []);
      byTime.get(key).push(person.id);
    }
  }

  return [...byTime.entries()].sort((a, b) => (a[0] < b[0] ? -1 : 1))
    .map(([time, staff]) => ({ time, staff }));
}

function nextOpenDays(ctx, serviceId, staffId, limit) {
  const zone = ctx.tenant.timezone;
  const now = DateTime.fromISO(ctx.now, { zone });
  const out = [];
  const horizon = Math.min(ctx.tenant.max_advance_days || 30, 60);
  for (let i = 0; i <= horizon && out.length < limit; i++) {
    const d = now.plus({ days: i });
    const iso = d.toFormat('yyyy-LL-dd');
    const slots = daySlots(ctx, serviceId, staffId, iso);
    if (!slots.length) continue;
    out.push({
      id: 'day:' + iso,
      title: i === 0 ? 'Today ' + d.toFormat('d LLL') : i === 1 ? 'Tomorrow ' + d.toFormat('d LLL') : d.toFormat('ccc d LLL'),
      description: slots.length + (slots.length === 1 ? ' time free' : ' times free'),
      iso, count: slots.length,
    });
  }
  return out;
}

// ---------- input parsing ----------
function readMsg(msg) {
  if (msg.kind === 'choice') return { kind: 'choice', id: String(msg.id || ''), text: String(msg.text || '') };
  if (msg.kind === 'text') return { kind: 'text', id: '', text: String(msg.text || '').trim() };
  return { kind: 'other', id: '', text: '' };
}
function pick(input, options) {
  if (input.kind === 'choice') return options.find((o) => o.id === input.id) || null;
  if (input.kind !== 'text') return null;
  const t = input.text.toLowerCase().trim();
  if (!t) return null;
  if (/^\d{1,2}$/.test(t)) return options[parseInt(t, 10) - 1] || null;
  const plain = (o) => String(o.title).toLowerCase().replace(/[\u2026\u25b8\u25c2]/g, '').trim();
  return options.find((o) => plain(o) === t)
    || options.find((o) => t.length >= 3 && plain(o).includes(t))
    || null;
}

// ---------- the conversation ----------
function respond(ctx, msg) {
  const t = ctx.tenant;
  const to = msg.wa_id;
  const input = readMsg(msg);
  const low = input.text.toLowerCase();
  const cur = t.currency;
  let s = (ctx.session && ctx.session.step) ? ctx.session : { step: 'service', data: {}, page: 0 };
  s.data = s.data || {};
  let action = 'none'; let args = null;

  const services = ctx.services || [];
  const known = ctx.customer && ctx.customer.name ? ctx.customer.name : '';

  const serviceRows = () => services.map((sv) => ({
    id: 'svc:' + sv.id, title: sv.name,
    description: [dur(sv.duration_min), money(sv.price, cur)].filter(Boolean).join(' \u00b7 '),
  }));

  const askService = (lead) => {
    const opts = serviceRows();
    if (!opts.length) return { reply: txt(to, 'Sorry, online booking is not set up yet. Please call us.'), state: s };
    s.step = 'service';
    const { rows } = paged(opts, s.page || 0);
    return {
      reply: lst(to, lead + '\n\nWhat would you like booked?\n' + rows.filter((r) => !r.id.startsWith('__'))
        .map((r, i) => (i + 1) + '. ' + r.title).join('\n'), 'Choose service', 'Our services', rows),
      state: s,
    };
  };

  const askStaff = () => {
    const people = staffForService(ctx, s.data.serviceId);
    if (people.length <= 1) {
      s.data.staffId = people.length ? people[0].id : null;
      s.data.staffName = people.length ? people[0].name : '';
      return askDay();
    }
    s.step = 'staff'; s.page = 0;
    const opts = [{ id: 'stf:any', title: 'Anyone', description: 'First available' }]
      .concat(people.map((p) => ({ id: 'stf:' + p.id, title: p.name })));
    const { rows } = paged(opts, 0);
    return { reply: lst(to, 'Who would you like?\n' + rows.filter((r) => !r.id.startsWith('__')).map((r, i) => (i + 1) + '. ' + r.title).join('\n'),
      'Choose person', 'Our team', rows), state: s };
  };

  const askDay = () => {
    const days = nextOpenDays(ctx, s.data.serviceId, s.data.staffId, 9);
    if (!days.length) {
      s.step = 'service'; s.data = {};
      return { reply: txt(to, 'Sorry, we have nothing free for that in the next ' + (t.max_advance_days || 30)
        + ' days. Reply MENU to try a different service, or call us and we will sort something out.'), state: s };
    }
    s.step = 'day'; s.days = days.map((d) => ({ id: d.id, title: d.title, description: d.description, iso: d.iso }));
    return { reply: lst(to, 'Which day suits you?\n' + days.map((d, i) => (i + 1) + '. ' + d.title).join('\n'),
      'Choose day', 'Next available', days), state: s };
  };

  const askTime = (lead) => {
    const slots = daySlots(ctx, s.data.serviceId, s.data.staffId, s.data.dayISO);
    if (!slots.length) return askDay();
    s.step = 'time'; s.page = 0;
    s.slots = slots.map((sl) => ({ id: 'tm:' + sl.time, title: sl.time, staff: sl.staff }));
    const { rows } = paged(s.slots, 0);
    return { reply: lst(to, (lead ? lead + '\n\n' : '') + 'Times free on ' + s.data.dayLabel + ':', 'Choose time',
      s.data.dayLabel, rows), state: s };
  };

  const askName = () => {
    if (known) { s.data.name = known; return askConfirm(); }
    s.step = 'name';
    return { reply: txt(to, 'Last thing - what name should I put the booking under?'), state: s };
  };

  const askConfirm = () => {
    s.step = 'confirm';
    const sv = services.find((x) => x.id === s.data.serviceId) || {};
    const price = money(sv.price, cur);
    return {
      reply: btns(to, 'Please check this is right:\n\n\u2022 ' + sv.name + (price ? ' (' + price + ')' : '')
        + '\n\u2022 ' + s.data.dayLabel + ' at ' + s.data.time
        + '\n\u2022 With ' + (s.data.staffName || 'first available')
        + '\n\u2022 ' + dur(sv.duration_min || 0)
        + '\n\nShall I book it?', [
        { id: 'ok', title: 'Confirm' }, { id: 'time', title: 'Change time' }, { id: 'menu', title: 'Start over' }]),
      state: s,
    };
  };

  // ----- global commands -----
  if (input.kind === 'text') {
    const naming = s.step === 'name';   // "Hi" is a greeting everywhere except where it might be a name
    if (naming ? /^(menu|restart|start over|reset)$/i.test(low)
               : /^(menu|restart|start over|start again|reset|hi|hello|hey|salam|book)$/i.test(low)) {
      s = { step: 'service', data: {}, page: 0 };
      const hi = known ? 'Hi ' + known.split(' ')[0] + '!' : 'Hi!';
      return { ...askService(hi + ' Welcome to ' + t.name + '.'), action, args };
    }
    if (/^(cancel|cancel booking)$/i.test(low)) {
      const mine = ctx.my_bookings || [];
      if (!mine.length) return { reply: txt(to, 'You have no upcoming bookings with us. Reply MENU to make one.'), state: s, action, args };
      const b = mine[0];
      const when = DateTime.fromISO(b.starts_at, { zone: t.timezone }).toFormat('ccc d LLL \u00b7 HH:mm');
      s = { step: 'cancelConfirm', data: { ref: b.ref }, page: 0 };
      return { reply: btns(to, 'Cancel this booking?\n\n\u2022 ' + b.service + '\n\u2022 ' + when + '\n\u2022 With ' + b.staff + '\n\u2022 Ref ' + b.ref,
        [{ id: 'yes', title: 'Yes, cancel it' }, { id: 'no', title: 'No, keep it' }]), state: s, action, args };
    }
    if (/^(my booking|my bookings|when|status)$/i.test(low)) {
      const mine = ctx.my_bookings || [];
      if (!mine.length) return { reply: txt(to, 'You have no upcoming bookings. Reply MENU to book one.'), state: s, action, args };
      const lines = mine.map((b) => '\u2022 ' + b.service + ' - ' + DateTime.fromISO(b.starts_at, { zone: t.timezone }).toFormat('ccc d LLL \u00b7 HH:mm')
        + ' with ' + b.staff + ' (ref ' + b.ref + ')');
      return { reply: txt(to, 'Your upcoming bookings:\n\n' + lines.join('\n') + '\n\nReply CANCEL to cancel, or MENU to book again.'), state: s, action, args };
    }
  }

  // ----- steps -----
  switch (s.step) {
    case 'service': {
      const opts = serviceRows();
      if (input.id === '__more') { s.page = (s.page || 0) + 1; return { ...askService('More services:'), action, args }; }
      if (input.id === '__first') { s.page = 0; return { ...askService('Our services:'), action, args }; }
      const opt = pick(input, opts);
      if (!opt) return { ...askService(known ? 'Sorry, I did not catch that.' : 'Welcome to ' + t.name + '.'), action, args };
      s.data.serviceId = parseInt(opt.id.split(':')[1], 10);
      s.data.serviceName = opt.title;
      s.page = 0;
      return { ...askStaff(), action, args };
    }
    case 'staff': {
      const people = staffForService(ctx, s.data.serviceId);
      const opts = [{ id: 'stf:any', title: 'Anyone' }].concat(people.map((p) => ({ id: 'stf:' + p.id, title: p.name })));
      const opt = pick(input, opts);
      if (!opt) return { ...askStaff(), action, args };
      if (opt.id === 'stf:any') { s.data.staffId = null; s.data.staffName = ''; }
      else {
        s.data.staffId = parseInt(opt.id.split(':')[1], 10);
        s.data.staffName = (people.find((p) => p.id === s.data.staffId) || {}).name || '';
      }
      return { ...askDay(), action, args };
    }
    case 'day': {
      const days = s.days && s.days.length ? s.days : nextOpenDays(ctx, s.data.serviceId, s.data.staffId, 9);
      const opt = pick(input, days);
      if (!opt) { s.days = days; return { ...askDay(), action, args }; }
      s.data.dayISO = opt.iso || opt.id.split(':')[1];
      s.data.dayLabel = opt.title;
      return { ...askTime(''), action, args };
    }
    case 'time': {
      const slots = s.slots && s.slots.length ? s.slots : [];
      if (input.id === '__more') {
        s.page = (s.page || 0) + 1;
        const { rows } = paged(slots, s.page);
        return { reply: lst(to, 'More times on ' + s.data.dayLabel + ':', 'Choose time', s.data.dayLabel, rows), state: s, action, args };
      }
      if (input.id === '__first') {
        s.page = 0;
        const { rows } = paged(slots, 0);
        return { reply: lst(to, 'Times free on ' + s.data.dayLabel + ':', 'Choose time', s.data.dayLabel, rows), state: s, action, args };
      }
      let opt = pick(input, slots);
      if (!opt && input.kind === 'text') {                       // "10:30", "1030", "10.30", "10"
        const m = low.replace(/[.\s]/g, ':').match(/^(\d{1,2}):?(\d{2})?$/);
        if (m) {
          const want = String(m[1]).padStart(2, '0') + ':' + (m[2] || '00');
          opt = slots.find((x) => x.title === want) || null;
        }
      }
      if (!opt) return { ...askTime('Sorry, that time is not on the list.'), action, args };
      s.data.time = opt.title;
      s.data.slotStaff = opt.staff || [];
      return { ...askName(), action, args };
    }
    case 'name': {
      if (input.kind !== 'text' || input.text.length < 2 || input.text.length > 60) {
        return { reply: txt(to, 'Please type the name for the booking.'), state: s, action, args };
      }
      s.data.name = input.text;
      return { ...askConfirm(), action, args };
    }
    case 'confirm': {
      const opt = pick(input, [{ id: 'ok', title: 'Confirm' }, { id: 'time', title: 'Change time' }, { id: 'menu', title: 'Start over' }])
        || (input.kind === 'text' && /^(yes|y|ok|confirm|book it)$/i.test(low) ? { id: 'ok' } : null);
      if (!opt) return { ...askConfirm(), action, args };
      if (opt.id === 'menu') { s = { step: 'service', data: {}, page: 0 }; return { ...askService('No problem, starting again.'), action, args }; }
      if (opt.id === 'time') return { ...askTime('No problem.'), action, args };

      const sv = services.find((x) => x.id === s.data.serviceId);
      if (!sv) { s = { step: 'service', data: {}, page: 0 }; return { ...askService('That service is no longer available.'), action, args }; }

      // recheck against the freshest availability before writing
      const live = daySlots(ctx, s.data.serviceId, s.data.staffId, s.data.dayISO).find((x) => x.time === s.data.time);
      if (!live) return { ...askTime('Sorry, that time has just been taken.'), action, args };

      const staffId = s.data.staffId || live.staff[0];
      const start = DateTime.fromISO(s.data.dayISO + 'T' + s.data.time, { zone: t.timezone });
      const end = start.plus({ minutes: sv.duration_min + (t.buffer_min || 0) });
      action = 'book';
      args = {
        staffId, serviceId: sv.id, name: s.data.name, blockMin: sv.duration_min + (t.buffer_min || 0),
        startISO: start.toISO({ suppressMilliseconds: true }),
        endISO: end.toISO({ suppressMilliseconds: true }),
        label: s.data.dayLabel + ' at ' + s.data.time,
        serviceName: sv.name,
        price: money(sv.price, cur),
      };
      s.step = 'booked';
      return { reply: null, state: s, action, args };
    }
    case 'cancelConfirm': {
      const opt = pick(input, [{ id: 'yes', title: 'Yes, cancel it' }, { id: 'no', title: 'No, keep it' }])
        || (input.kind === 'text' && /^(yes|y)$/i.test(low) ? { id: 'yes' } : null);
      if (!opt) {
        return { reply: btns(to, 'Sorry - cancel that booking, yes or no?',
          [{ id: 'yes', title: 'Yes, cancel it' }, { id: 'no', title: 'No, keep it' }]), state: s, action, args };
      }
      if (opt.id === 'no') { const ref = s.data.ref; s = { step: 'service', data: {}, page: 0 };
        return { reply: txt(to, 'No problem, booking ' + ref + ' is still in the diary. Reply MENU if you need anything else.'), state: s, action, args }; }
      action = 'cancel'; args = { ref: s.data.ref };
      s = { step: 'service', data: {}, page: 0 };
      return { reply: null, state: s, action, args };
    }
    case 'booked':
    default:
      return { ...askService(known ? 'Hi ' + known.split(' ')[0] + '!' : 'Hi!'), action, args };
  }
}

// ---------- run ----------
for (const it of $input.all()) {
  const row = it.json;
  const ctx = row.ctx;
  const msg = row.msg || {};
  if (!ctx || !ctx.tenant) continue;        // unknown WhatsApp number - not one of our salons
  if (row.fresh === false) continue;        // Meta re-delivered a message we already answered
  if (!msg.wa_id || msg.kind === 'skip') continue;

  const t = ctx.tenant;
  const r = respond(ctx, msg);

  const common = {
    tenant_id: t.id,
    wa_id: msg.wa_id,
    token: t.wa_token,
    phone_number_id: t.phone_number_id,
    graph_version: msg.graph_version || 'v25.0',
    timezone: t.timezone,
    owner_wa: t.owner_wa || '',
    owner_template: t.owner_template || '',
    salon_name: t.name,
    state: JSON.stringify(r.state || {}),
    action: r.action,
    waPayload: r.reply,
  };

  if (r.action === 'book') {
    OUT.push({ json: { ...common,
      sql: 'SELECT book_slot($1::int,$2::int,$3::int,$4,$5,$6::timestamptz,$7::timestamptz) AS r, $8::jsonb AS pass',
      params: [t.id, r.args.staffId, r.args.serviceId, msg.wa_id, r.args.name, r.args.startISO, r.args.endISO,
        JSON.stringify({ ...common, booking: r.args, session: r.state })],
    } });
  } else if (r.action === 'cancel') {
    OUT.push({ json: { ...common,
      sql: 'SELECT cancel_booking($1::int,$2,$3) AS r, $4::jsonb AS pass',
      params: [t.id, msg.wa_id, r.args.ref,
        JSON.stringify({ ...common, booking: r.args, session: r.state })],
    } });
  } else {
    OUT.push({ json: common });
  }
}
return OUT;

// ===== Finalize Reply =====
// The database has now spoken. Turn its answer into the customer's message.
// This is where a lost race becomes a helpful list instead of an error.
const clip = (s, n) => (String(s).length > n ? String(s).slice(0, n - 1) + '\u2026' : String(s));
const base = (to) => ({ messaging_product: 'whatsapp', recipient_type: 'individual', to });
const txt = (to, body) => ({ ...base(to), type: 'text', text: { preview_url: false, body: clip(body, 4096) } });
const lst = (to, body, buttonText, sectionTitle, rows) => ({
  ...base(to), type: 'interactive',
  interactive: { type: 'list', body: { text: clip(body, 1024) },
    action: { button: clip(buttonText, 20), sections: [{ title: clip(sectionTitle, 24),
      rows: rows.slice(0, 10).map((r) => { const o = { id: clip(r.id, 200), title: clip(r.title, 24) };
        if (r.description) o.description = clip(r.description, 72); return o; }) }] } },
});

const out = [];
for (const it of $input.all()) {
  const r = it.json.r || {};
  const p = it.json.pass || {};
  const to = p.wa_id;
  const b = p.booking || {};
  let session = p.session || { step: 'service', data: {} };
  let reply; let notifyOwner = false;

  if (p.action === 'book') {
    if (r.ok) {
      notifyOwner = !!(p.owner_wa && p.owner_template);
      reply = txt(to, 'Booked \u2705\n\n\u2022 ' + (r.service || b.serviceName) + (b.price ? ' (' + b.price + ')' : '')
        + '\n\u2022 ' + b.label + '\n\u2022 With ' + (r.staff || '') + '\n\u2022 Ref ' + r.ref
        + '\n\nSee you at ' + p.salon_name + '. Reply CANCEL if your plans change.');
      session = { step: 'booked', data: {}, ref: r.ref };
    } else if (r.reason === 'taken') {
      // Someone confirmed the same minute. Offer what is genuinely left of this day:
      // drop every cached time that overlaps the slot just taken - for that stylist only,
      // since a colleague may still be free at the same time.
      const mins = (t) => (+String(t).slice(0, 2)) * 60 + (+String(t).slice(3, 5));
      const takenTime = (b.label || '').split(' at ')[1] || '';
      const blockMin = Number(b.blockMin) || 0;
      const from = mins(takenTime); const until = from + blockMin;
      const left = (session.slots || []).filter((s) => {
        if (!/^\d{2}:\d{2}$/.test(s.title) || !takenTime) return s.title !== takenTime;
        const s0 = mins(s.title);
        if (!(s0 < until && s0 + blockMin > from)) return true;      // no clash
        const others = (s.staff || []).filter((id) => id !== b.staffId);
        s.staff = others;
        return others.length > 0;                                     // a colleague is still free
      });
      if (left.length) {
        session = { ...session, step: 'time', page: 0, slots: left };
        const rows = left.length > 10 ? left.slice(0, 9).concat([{ id: '__more', title: 'More \u25b8' }]) : left;
        reply = lst(to, 'Sorry - someone booked ' + (b.label || 'that slot') + ' moments before you. These are still free:',
          'Choose time', clip(String(session.data && session.data.dayLabel || 'Other times'), 24), rows);
      } else {
        session = { step: 'day', data: session.data || {} };
        reply = txt(to, 'Sorry - someone booked ' + (b.label || 'that slot') + ' moments before you, and that was the last time free that day. Reply OK and I will show you the next available days.');
      }
    } else if (r.reason === 'past') {
      session = { step: 'service', data: {} };
      reply = txt(to, 'That time has already passed. Reply MENU and we will start again.');
    } else {
      session = { step: 'service', data: {} };
      reply = txt(to, 'Sorry, that is no longer available. Reply MENU to start again.');
    }
  } else if (p.action === 'cancel') {
    if (r.ok) reply = txt(to, 'Cancelled \u274c\n\nBooking ' + r.ref + ' (' + (r.service || '') + ') is no longer in the diary.\n\nReply MENU whenever you want to rebook.');
    else reply = txt(to, 'I could not find that booking. Reply MY BOOKINGS to see what is in the diary.');
  } else {
    reply = txt(to, 'Reply MENU to start again.');
  }

  const ownerPayload = notifyOwner ? {
    messaging_product: 'whatsapp', to: String(p.owner_wa).replace(/\D/g, ''), type: 'template',
    template: { name: p.owner_template, language: { code: p.owner_lang || 'en' },
      components: [{ type: 'body', parameters: [
        { type: 'text', text: clip(b.name || 'Customer', 60) },
        { type: 'text', text: clip(r.service || b.serviceName || '', 60) },
        { type: 'text', text: clip((b.label || '') + ' with ' + (r.staff || ''), 60) }] }] },
  } : null;

  out.push({ json: { ...p, waPayload: reply, state: JSON.stringify(session), notifyOwner, ownerPayload, booked: !!(p.action === 'book' && r.ok), ref: r.ref || '' } });
}
return out;
